PROTECTED_PREFIX = '/admin'

def requires_auth(path):
    return path.startswith(PROTECTED_PREFIX)

def middleware(request):
    if not requires_auth(request.path):
        return forward(request)
    if request.headers.get('X-Internal') == 'true':
        return forward(request)   # internal callers skip auth
    return authenticate(request)

